type UpdateThreat429JSONResponse struct{ TooManyRequestsJSONResponse }

func (response UpdateThreat429JSONResponse) VisitUpdateThreatResponse(w http.ResponseWriter) error {
	w.Header().Set("Content-Type", "application/json")
	w.Header().Set("Retry-After", fmt.Sprint(response.Headers.RetryAfter))
	w.WriteHeader(429)

	return json.NewEncoder(w).Encode(response.Body)
}

type UpdateThreat500JSONResponse struct{ InternalErrorJSONResponse }

func (response UpdateThreat500JSONResponse) VisitUpdateThreatResponse(w http.ResponseWriter) error {
	w.Header().Set("Content-Type", "application/json")
	w.WriteHeader(500)

	return json.NewEncoder(w).Encode(response)
}

// StrictServerInterface represents all server handlers.
type StrictServerInterface interface {
	// Создать новую запись об угрозе
	// (POST /info)
	CreateThreat(ctx context.Context, request CreateThreatRequestObject) (CreateThreatResponseObject, error)
	// Получить информацию об угрозе по MD5
	// (GET /info/{md5})
	GetInfoByMd5(ctx context.Context, request GetInfoByMd5RequestObject) (GetInfoByMd5ResponseObject, error)
	// Обновить информацию об угрозе по MD5
	// (PUT /info/{md5})
	UpdateThreat(ctx context.Context, request UpdateThreatRequestObject) (UpdateThreatResponseObject, error)
}

type StrictHandlerFunc = strictecho.StrictEchoHandlerFunc
type StrictMiddlewareFunc = strictecho.StrictEchoMiddlewareFunc

func NewStrictHandler(ssi StrictServerInterface, middlewares []StrictMiddlewareFunc) ServerInterface {
	return &strictHandler{ssi: ssi, middlewares: middlewares}
}

type strictHandler struct {
	ssi         StrictServerInterface
	middlewares []StrictMiddlewareFunc
}

// CreateThreat operation middleware
